import type { StateCode } from "@/config/defaults/stateTaxTable";
import type { Cents, Micros } from "@/types/units";

export const LOAN_TERMS = [15, 20, 30] as const;
export type LoanTerm = (typeof LOAN_TERMS)[number];

export type DownPaymentMode = "percent" | "amount";

/** Fields whose validation message is shown after the user leaves the field. */
export type ErrorField =
	| "homePrice"
	| "downPayment"
	| "interestRate"
	| "annualTaxOverride"
	| "annualInsurance"
	| "extraAnnualInsurance"
	| "monthlyHoa"
	| "monthlyOther"
	| "pmiRate";

/** Raw text the user typed, plus which down payment form is the source. */
export interface CalculatorInputs {
	homePrice: string;
	downPaymentPercent: string;
	downPaymentAmount: string;
	downPaymentMode: DownPaymentMode;
	termYears: LoanTerm;
	interestRate: string;
	state: StateCode;
	/** Annual property tax typed by the user. Empty means use the state rate. */
	annualTaxOverride: string;
	/** Empty means use the national default. */
	annualInsurance: string;
	/** Optional extra annual premium (flood, wind). Empty means none. */
	extraAnnualInsurance: string;
	monthlyHoa: string;
	/** One optional monthly amount, not a list. */
	monthlyOther: string;
	/** PMI toggle. Only matters when LTV is above 80%. */
	pmiOn: boolean;
	/** Annual PMI rate in percent. Empty means use the default. */
	pmiRate: string;
}

export interface CalculatorState {
	inputs: CalculatorInputs;
	touched: Partial<Record<ErrorField, boolean>>;
}

export type EditableField =
	| "homePrice"
	| "downPaymentPercent"
	| "downPaymentAmount"
	| "interestRate"
	| "annualTaxOverride"
	| "annualInsurance"
	| "extraAnnualInsurance"
	| "monthlyHoa"
	| "monthlyOther"
	| "pmiRate";

export type CalculatorAction =
	| { type: "edit"; field: EditableField; value: string }
	| { type: "blur"; field: EditableField }
	| { type: "setDownPaymentMode"; mode: DownPaymentMode }
	| { type: "setTerm"; years: LoanTerm }
	| { type: "setState"; state: StateCode }
	| { type: "setPmiOn"; on: boolean };

export interface LoanDerivation {
	homePrice: Cents;
	downPayment: Cents;
	downPaymentPercent: Micros;
	loanAmount: Cents;
	/** Monthly principal and interest for the fixed-rate loan. */
	monthlyPrincipalAndInterest: Cents;
	/** loan / price, in millionths. 80.00% is 800000. */
	ltv: Micros;
	interestRate: Micros;
	termYears: LoanTerm;
}

export type InputErrors = Partial<Record<ErrorField, string>>;

export interface DerivedLoan {
	errors: InputErrors;
	/** Present only when every input is valid. */
	loan: LoanDerivation | null;
}
import { parseMoney } from "@/lib/money";
import { parseRate } from "@/lib/rate";
import {
	centsToFieldText,
	downPaymentFromPercent,
	MAX_HOME_PRICE,
	microsToPercentText,
	percentFromDownPayment,
} from "./loanMath";
import type {
	CalculatorAction,
	CalculatorInputs,
	CalculatorState,
	EditableField,
	ErrorField,
	LoanTerm,
} from "./types";

export const DEFAULT_TERM: LoanTerm = 30;

export const initialCalculatorState: CalculatorState = {
	inputs: {
		homePrice: "500,000",
		downPaymentPercent: "20.00",
		downPaymentAmount: "100,000.00",
		downPaymentMode: "percent",
		termYears: DEFAULT_TERM,
		interestRate: "6.50",
		state: "NJ",
		annualTaxOverride: "",
		annualInsurance: "",
		extraAnnualInsurance: "",
		monthlyHoa: "",
		monthlyOther: "",
		pmiOn: true,
		pmiRate: "",
	},
	touched: {},
};

/**
 * Rewrites the non-source down payment field from the source field so both
 * forms agree. Leaves the other field alone when the source is not valid yet.
 */
export const syncDownPayment = (inputs: CalculatorInputs): CalculatorInputs => {
	const price = parseMoney(inputs.homePrice);
	if (!price.ok || price.value <= 0 || price.value > MAX_HOME_PRICE) {
		return inputs;
	}
	if (inputs.downPaymentMode === "percent") {
		const percent = parseRate(inputs.downPaymentPercent);
		if (!percent.ok || percent.value > 1_000_000) return inputs;
		const cents = downPaymentFromPercent(price.value, percent.value);
		return { ...inputs, downPaymentAmount: centsToFieldText(cents) };
	}
	const amount = parseMoney(inputs.downPaymentAmount);
	if (!amount.ok || amount.value > price.value) return inputs;
	const percent = percentFromDownPayment(price.value, amount.value);
	return { ...inputs, downPaymentPercent: microsToPercentText(percent) };
};

/** Edits to these fields can change the synced down payment counterpart. */
const PRICE_LINKED_FIELDS: ReadonlySet<EditableField> = new Set([
	"homePrice",
	"downPaymentPercent",
	"downPaymentAmount",
]);

const errorFieldFor = (field: EditableField): ErrorField =>
	field === "downPaymentPercent" || field === "downPaymentAmount"
		? "downPayment"
		: field;

export const calculatorReducer = (
	state: CalculatorState,
	action: CalculatorAction,
): CalculatorState => {
	switch (action.type) {
		case "edit":
			return {
				...state,
				inputs: { ...state.inputs, [action.field]: action.value },
			};
		case "blur": {
			const touched = { ...state.touched, [errorFieldFor(action.field)]: true };
			// Price and down payment edits both change the synced counterpart.
			const inputs = PRICE_LINKED_FIELDS.has(action.field)
				? syncDownPayment(state.inputs)
				: state.inputs;
			return { inputs, touched };
		}
		case "setDownPaymentMode":
			// Both forms were already synced on blur, so only the source changes.
			return {
				...state,
				inputs: { ...state.inputs, downPaymentMode: action.mode },
			};
		case "setTerm":
			return { ...state, inputs: { ...state.inputs, termYears: action.years } };
		case "setPmiOn":
			return { ...state, inputs: { ...state.inputs, pmiOn: action.on } };
		case "setState":
			return { ...state, inputs: { ...state.inputs, state: action.state } };
	}
};
import { useDeferredValue, useMemo, useReducer } from "react";
import { buildSchedule } from "@/lib/amortization";
import {
	calculatorReducer,
	initialCalculatorState,
} from "../calculatorReducer";
import { deriveLoan } from "../loanMath";
import { deriveMonthlyCosts } from "../monthlyCosts";
import { buildMonthlyEstimate } from "../monthlyEstimate";
import { derivePmi } from "../pmi";
import { derivePropertyTax } from "../propertyTax";

/**
 * Owns the calculator input state. Typing updates `state` immediately; the
 * loan derivation reads a deferred copy so a slow recalculation never blocks
 * keystrokes (INP).
 */
export const useCalculatorInputs = () => {
	const [state, dispatch] = useReducer(
		calculatorReducer,
		initialCalculatorState,
	);
	const deferredInputs = useDeferredValue(state.inputs);
	const derived = useMemo(() => deriveLoan(deferredInputs), [deferredInputs]);
	const propertyTax = useMemo(
		() => derivePropertyTax(deferredInputs),
		[deferredInputs],
	);
	const monthlyCosts = useMemo(
		() => deriveMonthlyCosts(deferredInputs),
		[deferredInputs],
	);
	const schedule = useMemo(() => {
		const loan = derived.loan;
		return loan
			? buildSchedule({
					loan: loan.loanAmount,
					rate: loan.interestRate,
					payments: loan.termYears * 12,
				})
			: null;
	}, [derived.loan]);
	const pmi = useMemo(
		() => derivePmi(deferredInputs, derived.loan, schedule),
		[deferredInputs, derived.loan, schedule],
	);
	const estimate = useMemo(
		() =>
			buildMonthlyEstimate(
				derived.loan,
				propertyTax.tax,
				monthlyCosts.costs,
				pmi.result,
			),
		[derived.loan, propertyTax.tax, monthlyCosts.costs, pmi.result],
	);
	return {
		state,
		dispatch,
		derived,
		propertyTax,
		monthlyCosts,
		pmi,
		estimate,
		schedule,
	};
};
import Card from "@/components/ui/Card";
import { useCalculatorInputs } from "../hooks/useCalculatorInputs";
import DownPaymentFields from "./DownPaymentFields";
import LoanSummary from "./LoanSummary";
import MonthlyCostsFields from "./MonthlyCostsFields";
import MonthlyCostsSummary from "./MonthlyCostsSummary";
import MonthlyEstimateCard from "./MonthlyEstimateCard";
import PmiFields from "./PmiFields";
import PmiSummary from "./PmiSummary";
import PropertyTaxFields from "./PropertyTaxFields";
import PropertyTaxSummary from "./PropertyTaxSummary";
import ScheduleTable from "./ScheduleTable";
import TermSelector from "./TermSelector";
import TextField from "./TextField";

const LoanCalculator = () => {
	const {
		state,
		dispatch,
		derived,
		propertyTax,
		monthlyCosts,
		pmi,
		estimate,
		schedule,
	} = useCalculatorInputs();
	const { inputs, touched } = state;
	// Show a message only after the user has left the field.
	const shown = (field: keyof typeof touched) =>
		touched[field]
			? (derived.errors[field] ??
				propertyTax.errors[field] ??
				monthlyCosts.errors[field] ??
				pmi.errors[field])
			: undefined;

	return (
		<div className="grid gap-6">
			<Card>
				<form
					noValidate
					onSubmit={(event) => event.preventDefault()}
					className="grid gap-5 sm:grid-cols-2"
				>
					<TextField
						className="sm:col-span-2"
						label="Home price"
						prefix="$"
						value={inputs.homePrice}
						error={shown("homePrice")}
						onChange={(value) =>
							dispatch({ type: "edit", field: "homePrice", value })
						}
						onBlur={() => dispatch({ type: "blur", field: "homePrice" })}
					/>
					<DownPaymentFields
						mode={inputs.downPaymentMode}
						percent={inputs.downPaymentPercent}
						amount={inputs.downPaymentAmount}
						error={shown("downPayment")}
						onModeChange={(mode) =>
							dispatch({ type: "setDownPaymentMode", mode })
						}
						onPercentChange={(value) =>
							dispatch({ type: "edit", field: "downPaymentPercent", value })
						}
						onAmountChange={(value) =>
							dispatch({ type: "edit", field: "downPaymentAmount", value })
						}
						onBlur={(field) => dispatch({ type: "blur", field })}
					/>
					<TermSelector
						value={inputs.termYears}
						onChange={(years) => dispatch({ type: "setTerm", years })}
					/>
					<TextField
						label="Interest rate"
						suffix="%"
						value={inputs.interestRate}
						error={shown("interestRate")}
						onChange={(value) =>
							dispatch({ type: "edit", field: "interestRate", value })
						}
						onBlur={() => dispatch({ type: "blur", field: "interestRate" })}
					/>
					<PropertyTaxFields
						state={inputs.state}
						override={inputs.annualTaxOverride}
						error={shown("annualTaxOverride")}
						onStateChange={(value) =>
							dispatch({ type: "setState", state: value })
						}
						onOverrideChange={(value) =>
							dispatch({ type: "edit", field: "annualTaxOverride", value })
						}
						onBlur={() =>
							dispatch({ type: "blur", field: "annualTaxOverride" })
						}
					/>
					<MonthlyCostsFields
						values={inputs}
						errorFor={shown}
						onChange={(field, value) =>
							dispatch({ type: "edit", field, value })
						}
						onBlur={(field) => dispatch({ type: "blur", field })}
					/>
					<PmiFields
						required={pmi.required}
						on={inputs.pmiOn}
						rate={inputs.pmiRate}
						error={shown("pmiRate")}
						onToggle={(on) => dispatch({ type: "setPmiOn", on })}
						onRateChange={(value) =>
							dispatch({ type: "edit", field: "pmiRate", value })
						}
						onBlur={() => dispatch({ type: "blur", field: "pmiRate" })}
					/>
				</form>
			</Card>
			<MonthlyEstimateCard estimate={estimate} />
			<LoanSummary loan={derived.loan} />
			<PropertyTaxSummary tax={propertyTax.tax} />
			<MonthlyCostsSummary costs={monthlyCosts.costs} />
			<PmiSummary result={pmi.result} />
			{schedule ? <ScheduleTable rows={schedule} /> : null}
		</div>
	);
};

export default LoanCalculator;
import { useMemo, useState } from "react";
import Button from "@/components/ui/Button";
import Card from "@/components/ui/Card";
import {
	lifetimeInterest,
	type ScheduleRow,
	summarizeByYear,
} from "@/lib/amortization";
import { formatMoney } from "@/lib/money";

interface ScheduleTableProps {
	rows: readonly ScheduleRow[];
}

type View = "monthly" | "yearly";

const VIEWS: { view: View; label: string }[] = [
	{ view: "monthly", label: "Monthly" },
	{ view: "yearly", label: "Yearly" },
];

const HEAD = "px-3 py-2 text-right font-medium";
const CELL = "px-3 py-2 text-right tabular-nums";

const ScheduleTable = ({ rows }: ScheduleTableProps) => {
	const [view, setView] = useState<View>("yearly");
	const years = useMemo(() => summarizeByYear(rows), [rows]);
	const totalInterest = useMemo(() => lifetimeInterest(rows), [rows]);

	if (rows.length === 0) {
		return (
			<Card>
				<h2 className="text-lg font-semibold">Amortization schedule</h2>
				<p className="mt-2 text-sm text-slate-700">
					There is no schedule because the loan amount is $0.
				</p>
			</Card>
		);
	}

	const periodLabel = view === "monthly" ? "Month" : "Year";
	const body =
		view === "monthly"
			? rows.map((row) => ({ key: row.month, label: row.month, ...row }))
			: years.map((row) => ({ key: row.year, label: row.year, ...row }));

	return (
		<Card className="grid gap-4">
			<div className="flex flex-wrap items-center justify-between gap-3">
				<div>
					<h2 className="text-lg font-semibold">Amortization schedule</h2>
					<p className="text-sm text-slate-600">
						Lifetime interest{" "}
						<strong className="font-semibold text-slate-900">
							{formatMoney(totalInterest)}
						</strong>{" "}
						over {rows.length} payments
					</p>
				</div>
				<fieldset>
					<legend className="sr-only">Schedule view</legend>
					{VIEWS.map((item) => (
						<Button
							key={item.view}
							variant={view === item.view ? "primary" : "secondary"}
							aria-pressed={view === item.view}
							onClick={() => setView(item.view)}
							className="px-3 py-1 first:rounded-r-none last:rounded-l-none"
						>
							{item.label}
						</Button>
					))}
				</fieldset>
			</div>
			<section
				// biome-ignore lint/a11y/noNoninteractiveTabindex: a scrollable region must be keyboard reachable
				tabIndex={0}
				aria-label={`${view === "monthly" ? "Monthly" : "Yearly"} amortization schedule`}
				className="max-h-96 overflow-auto rounded-md ring-1 ring-slate-200 focus-visible:outline-2 focus-visible:outline-brand-500"
			>
				<table className="w-full min-w-[32rem] text-sm">
					<caption className="sr-only">
						{view === "monthly" ? "Payment" : "Yearly totals"} by{" "}
						{periodLabel.toLowerCase()}: payment, principal, interest and
						remaining balance
					</caption>
					<thead className="sticky top-0 bg-slate-100 text-slate-700">
						<tr>
							<th scope="col" className="px-3 py-2 text-left font-medium">
								{periodLabel}
							</th>
							<th scope="col" className={HEAD}>
								Payment
							</th>
							<th scope="col" className={HEAD}>
								Principal
							</th>
							<th scope="col" className={HEAD}>
								Interest
							</th>
							<th scope="col" className={HEAD}>
								Balance
							</th>
						</tr>
					</thead>
					<tbody className="divide-y divide-slate-100">
						{body.map((row) => (
							<tr key={row.key}>
								<th scope="row" className="px-3 py-2 text-left font-normal">
									{row.label}
								</th>
								<td className={CELL}>{formatMoney(row.payment)}</td>
								<td className={CELL}>{formatMoney(row.principal)}</td>
								<td className={CELL}>{formatMoney(row.interest)}</td>
								<td className={CELL}>{formatMoney(row.balance)}</td>
							</tr>
						))}
					</tbody>
				</table>
			</section>
		</Card>
	);
};

export default ScheduleTable;
import { formatMoney } from "@/lib/money";
import { formatPercent } from "@/lib/rate";
import type { LoanDerivation } from "../types";

interface LoanSummaryProps {
	loan: LoanDerivation | null;
}

const LoanSummary = ({ loan }: LoanSummaryProps) => (
	<section
		aria-labelledby="loan-summary-heading"
		className="rounded-lg bg-brand-50 p-6 ring-1 ring-brand-500/30"
	>
		<h2
			id="loan-summary-heading"
			className="text-sm font-medium text-slate-700"
		>
			Monthly principal and interest
		</h2>
		{/* Announce result changes without moving focus. */}
		<div aria-live="polite">
			{loan ? (
				<>
					<p className="mt-1 text-4xl font-bold tracking-tight text-slate-900">
						{formatMoney(loan.monthlyPrincipalAndInterest)}
						<span className="ml-1 text-base font-normal text-slate-600">
							/ month
						</span>
					</p>
					<dl className="mt-4 grid grid-cols-1 gap-4 border-t border-slate-300/60 pt-4 text-sm sm:grid-cols-3">
						<div>
							<dt className="text-slate-600">Loan amount</dt>
							<dd className="mt-0.5 text-lg font-semibold text-slate-900">
								{formatMoney(loan.loanAmount)}
							</dd>
						</div>
						<div>
							<dt className="text-slate-600">Loan-to-value (LTV)</dt>
							<dd className="mt-0.5 text-lg font-semibold text-slate-900">
								{formatPercent(loan.ltv, 2)}
							</dd>
						</div>
						<div>
							<dt className="text-slate-600">Down payment</dt>
							<dd className="mt-0.5 text-lg font-semibold text-slate-900">
								{formatMoney(loan.downPayment)}
								<span className="ml-1 text-sm font-normal text-slate-600">
									({formatPercent(loan.downPaymentPercent, 2)})
								</span>
							</dd>
						</div>
					</dl>
				</>
			) : (
				<p className="mt-1 text-base text-slate-700">
					Fix the highlighted fields to see the payment, loan amount and LTV.
				</p>
			)}
		</div>
	</section>
);

export default LoanSummary;
import { useId } from "react";
import { LOAN_TERMS, type LoanTerm } from "../types";

interface TermSelectorProps {
	value: LoanTerm;
	onChange: (years: LoanTerm) => void;
}

const TermSelector = ({ value, onChange }: TermSelectorProps) => {
	const name = useId();
	return (
		<fieldset>
			<legend className="text-sm font-medium text-slate-800">Loan term</legend>
			<div className="mt-1 grid grid-cols-3 gap-2">
				{LOAN_TERMS.map((years) => (
					<label key={years} className="relative">
						<input
							type="radio"
							name={name}
							value={years}
							checked={value === years}
							onChange={() => onChange(years)}
							className="peer sr-only"
						/>
						<span className="flex cursor-pointer items-center justify-center rounded-md bg-white px-3 py-2 text-sm font-medium text-slate-700 ring-1 ring-slate-300 peer-checked:bg-brand-600 peer-checked:text-white peer-checked:ring-brand-600 peer-focus-visible:outline-2 peer-focus-visible:outline-offset-2 peer-focus-visible:outline-brand-500">
							{years} years
						</span>
					</label>
				))}
			</div>
		</fieldset>
	);
};

export default TermSelector;
import { useId } from "react";
import { cn } from "@/lib/cn";

interface TextFieldProps {
	label: string;
	value: string;
	onChange: (value: string) => void;
	onBlur: () => void;
	error?: string | undefined;
	hint?: string;
	prefix?: string;
	suffix?: string;
	readOnly?: boolean;
	className?: string;
}

const TextField = ({
	label,
	value,
	onChange,
	onBlur,
	error,
	hint,
	prefix,
	suffix,
	readOnly = false,
	className,
}: TextFieldProps) => {
	const id = useId();
	const errorId = `${id}-error`;
	const hintId = `${id}-hint`;
	const describedBy =
		[error ? errorId : null, hint ? hintId : null].filter(Boolean).join(" ") ||
		undefined;

	return (
		<div className={className}>
			<label htmlFor={id} className="block text-sm font-medium text-slate-800">
				{label}
			</label>
			<div
				className={cn(
					"mt-1 flex items-center rounded-md bg-white ring-1 ring-slate-300 focus-within:ring-2 focus-within:ring-brand-500",
					error && "ring-2 ring-red-600 focus-within:ring-red-600",
					readOnly && "bg-slate-100 text-slate-600",
				)}
			>
				{prefix ? (
					<span aria-hidden="true" className="pl-3 text-slate-500">
						{prefix}
					</span>
				) : null}
				<input
					id={id}
					type="text"
					inputMode="decimal"
					autoComplete="off"
					value={value}
					readOnly={readOnly}
					aria-readonly={readOnly || undefined}
					aria-invalid={error ? true : undefined}
					aria-describedby={describedBy}
					onChange={(event) => onChange(event.target.value)}
					onBlur={onBlur}
					className="w-full min-w-0 bg-transparent px-3 py-2 text-base outline-none"
				/>
				{suffix ? (
					<span aria-hidden="true" className="pr-3 text-slate-500">
						{suffix}
					</span>
				) : null}
			</div>
			{hint ? (
				<p id={hintId} className="mt-1 text-xs text-slate-500">
					{hint}
				</p>
			) : null}
			{error ? (
				<p id={errorId} className="mt-1 text-sm font-medium text-red-700">
					<span aria-hidden="true">⚠ </span>
					{error}
				</p>
			) : null}
		</div>
	);
};

export default TextField;

